        let read1 = get(R1.self).unsafelyUnwrapped
        let read2 = get(R2.self).unsafelyUnwrapped
        try modify(W1.self) { (write1: inout W1) in
            try modify(W2.self) { (write2: inout W2) in
                try modify(W3.self) { (write3: inout W3) in
